import numpy as np
def wavelength_to_color(nm):
    table = [(380, "紫"), (430, "青"), (490, "緑"), (550, "黄"), (590, "橙"), (640, "赤"), (781, None)]
    if nm < 380: return "紫外線（見えない）"
    if nm > 780: return "赤外線（見えない）"
    for (lo, name), (hi, _) in zip(table, table[1:]):
        if lo <= nm < hi:
            return name
for nm in [350, 400, 470, 520, 570, 610, 700, 900]:
    f = 3e8 / (nm * 1e-9)
    print(f"{nm}nm: {wavelength_to_color(nm)}  周波数 {f:.2e} Hz")

import numpy as np
def V_photopic(l):  return np.exp(-285.4 * (l / 1000 - 0.555) ** 2)
def V_scotopic(l):  return np.exp(-321.9 * (l / 1000 - 0.507) ** 2)
def vision_mode(cd_m2):
    if cd_m2 >= 3:     return "明所視（錐体）"
    if cd_m2 <= 1e-3:  return "暗所視（桿体）"
    return "薄明視（両方）"
for L in [1e5, 100, 0.1, 1e-4]:
    print(f"{L:g} cd/m2 -> {vision_mode(L)}")
for l in [500, 600]:
    print(f"{l}nm: 明所 {V_photopic(l):.2f} / 暗所 {V_scotopic(l):.2f}")

import numpy as np
M = np.array([[0.4124, 0.3576, 0.1805],
              [0.2126, 0.7152, 0.0722],
              [0.0193, 0.1192, 0.9505]])
def to_lin(c):
    c = np.asarray(c, float) / 255
    return np.where(c <= 0.04045, c / 12.92, ((c + 0.055) / 1.055) ** 2.4)
def chromaticity(rgb):
    X, Y, Z = M @ to_lin(rgb)
    return X / (X + Y + Z), Y / (X + Y + Z), Y
