import numpy as np
coef = {"BT.601": (0.299, 0.587, 0.114),
        "BT.709": (0.2126, 0.7152, 0.0722),
        "BT.2020": (0.2627, 0.6780, 0.0593)}
def to_ycbcr(rgb, std):
    kr, kg, kb = coef[std]
    r, g, b = rgb
    y = kr * r + kg * g + kb * b
    cb = (b - y) / (2 * (1 - kb))            # -0.5〜0.5 に正規化した色差
    cr = (r - y) / (2 * (1 - kr))
    return np.round([y, cb, cr], 4)
for std in coef:
    print(std, "緑(0,1,0) ->", to_ycbcr((0, 1, 0), std))

import numpy as np
def xyz_to_luv(X, Y, Z, white=(0.95047, 1.0, 1.08883)):
    def uv(X, Y, Z):
        d = X + 15 * Y + 3 * Z
        return 4 * X / d, 9 * Y / d
    un, vn = uv(*white)
    u, v = uv(X, Y, Z)
    t = Y / white[1]
    L = 116 * np.cbrt(t) - 16 if t > (6/29)**3 else (29/3)**3 * t
    return L, 13 * L * (u - un), 13 * L * (v - vn), (u, v)
for name, xyz in [("白", (0.95047, 1.0, 1.08883)), ("赤", (0.4124, 0.2126, 0.0193)), ("緑", (0.3576, 0.7152, 0.1192))]:
    L, us, vs, (u, v) = xyz_to_luv(*xyz)
    print(f"{name}: u'={u:.3f} v'={v:.3f}  L*={L:.1f} u*={us:.1f} v*={vs:.1f}")

import numpy as np
def rgb_to_cmyk(r, g, b):
    c, m, y = 1 - r / 255, 1 - g / 255, 1 - b / 255   # 補色（CMY）
    k = min(c, m, y)                                  # 共通の灰色成分を墨に
    if k == 1:
        return 0, 0, 0, 1
    return c - k, m - k, y - k, k
def cmyk_to_rgb(c, m, y, k):
    return [round(255 * (1 - min(1, v + k))) for v in (c, m, y)]
for rgb in [(255, 0, 0), (200, 150, 50), (128, 128, 128)]:
    cmyk = rgb_to_cmyk(*rgb)
    print(rgb, "-> CMYK", np.round(cmyk, 3), "-> 戻す", cmyk_to_rgb(*cmyk))

import numpy as np
def lightness(Y):                          # 相対輝度(0〜1) -> CIE明度 L*
    Y = np.asarray(Y, float)
    return np.where(Y > (6/29)**3, 116 * np.cbrt(Y) - 16, (29/3)**3 * Y)
for Y in [1.0, 0.5, 0.18, 0.09, 0.01]:
    print(f"Y={Y:4.2f} -> L*={lightness(Y):5.1f}")
